import { test } from 'node:test';
import assert from 'node:assert/strict';
import { deepMerge } from '../merge.js';
test('merges', () => {
  const a = { x: 1, n: { a: 1, b: [1, 2] }, d: new Date(0) };
  const b = { y: 2, n: { b: [3], c: { z: 1 } }, x: undefined };
  const out = deepMerge(a, b, { n: { a: 5 } });
  assert.deepEqual(out, { x: 1, y: 2, n: { a: 5, b: [3], c: { z: 1 } }, d: new Date(0) });
});
test('no mutation', () => {
  const a = { n: { a: 1 } };
  const b = { n: { b: 2 } };
  const out = deepMerge(a, b);
  out.n.c = 3;
  assert.deepEqual(a, { n: { a: 1 } });
  assert.deepEqual(b, { n: { b: 2 } });
});
test('empty', () => assert.deepEqual(deepMerge(), {}));

solution.merge.js:
const plain = (v) => v !== null && typeof v === 'object' && Object.getPrototypeOf(v) === Object.prototype;
export function deepMerge(...objects) {
  const out = {};
  for (const o of objects) {
    for (const [k, v] of Object.entries(o ?? {})) {
      if (v === undefined) continue;
      out[k] = plain(v) ? deepMerge(plain(out[k]) ? out[k] : {}, v) : v;
    }
  }
  return out;
}
